const decode = value => new TextDecoder().decode(Uint8Array.from(atob(value), char => char.charCodeAt(0)));
const files = {
  "/": ["", "text/html; charset=utf-8"],
  "/index.html": ["", "text/html; charset=utf-8"],
  "/app.js": ["", "application/javascript; charset=utf-8"],
  "/styles.css": ["", "text/css; charset=utf-8"],
};
const transactionUnitPricePatch = "";

export function staticAsset(pathname) {
  const file = files[pathname];
  if (!file) return null;
  let content = decode(file[0]);
  if (pathname === "/app.js") content += `\n${decode(transactionUnitPricePatch)}`;
  if (pathname === "/" || pathname === "/index.html") content = content.replace('<th>수량</th><th>금액</th><th>수수료</th><th></th>', '<th>수량</th><th>단가</th><th>금액</th><th>수수료</th><th></th>');
  return new Response(content, { headers: { "content-type": file[1], "cache-control": "no-store" } });
}
